package com.ruoyi.paiflow.service;

import com.alibaba.fastjson2.*;
import com.ruoyi.paiflow.domain.WorkflowVersionRecord;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.support.StaticListableBeanFactory;
import static org.junit.jupiter.api.Assertions.*;

/** 实际WF版本→Run/租约→检查点Mapper；原算法结果另由Python消费真实assignment核对。 */
class StaticQuestionAnswerPersistenceTest extends StaticQuestionAnswerTestFixture {
    @Test void originalCanvasCompilesV3WithoutChangingRawThenQueuesClaimsBeginsAndPreservesNullBytes() throws Exception {
        var raw=canvas();String before=raw.toJSONString(JSONWriter.Feature.WriteMapNullValue);long v=version(raw);var stored=workflowMapper.version(v);
        assertEquals(DslCodec.V3,stored.getExecutionCodec());assertEquals(raw,JSON.parseObject(stored.getCanvasJson()));assertEquals(before,raw.toJSONString(JSONWriter.Feature.WriteMapNullValue));
        var fixed=workflows.runtimeSnapshot(v);var p=params(fixed.execution());assertEquals(1,p.get("timeout"));assertEquals(false,p.get("needReply"));assertEquals(1,p.getJSONObject("directAnswer").get("maxRetryCounts"));assertEquals("",p.get("domain"));assertEquals("",p.get("appId"));assertTrue(p.containsKey("opaqueNull"));assertNull(p.get("opaqueNull"));
        // 持久JSON数值为BigDecimal，typed重建为Double；固定原字节与hash而非Java盒装对象比较。
        var reconstructed=WorkflowModelCompiler.reconstruct(raw,new JSONObject(),DslCodec.V3);String goldenHash="168c064b1484b28d0a7e18d13c41792d313eb8e1e6be70bb9d66a52fd6e832b0";
        assertEquals(goldenHash,stored.getDslHash());assertEquals(goldenHash,DslCodec.fixedExecutionHash(reconstructed,DslCodec.V3));assertEquals(goldenHash,DslCodec.fixedExecutionHash(fixed.execution(),DslCodec.V3));
        assertArrayEquals(Base64.getDecoder().decode(stored.getCanonicalDslBase64()),Base64.getDecoder().decode(DslCodec.canonicalDslBase64(reconstructed,DslCodec.V3)));assertEquals(stored.getCanonicalDslBase64(),DslCodec.canonicalDslBase64(fixed.execution(),DslCodec.V3));
        var task=task(v);assertEquals(RunJsonCodec.V2,runMapper.find(task.getString("runId")).getRunJsonCodec());assertEquals(fixed.execution(),task.get("dsl"));assertEquals(goldenHash,task.get("dslHash"));assertArrayEquals(Base64.getDecoder().decode(stored.getCanonicalDslBase64()),Base64.getDecoder().decode(task.getString("dslCanonicalBase64")));assertEquals(fixed.execution(),JSON.parseObject(new String(Base64.getDecoder().decode(task.getString("dslCanonicalBase64")),StandardCharsets.UTF_8)));assertEquals("read_only",task.getJSONObject("effectPolicy").get("mode"));assertTrue(task.getJSONObject("resourceSnapshots").isEmpty());
        assertTrue(leases.beginExecution(task.getString("runId"),worker,task.getString("leaseId"),task.getIntValue("attempt")).getBooleanValue("begun"));assertEquals(409,denied(()->leases.beginExecution(task.getString("runId"),worker,task.getString("leaseId"),task.getIntValue("attempt"))));
        Files.createDirectories(Path.of("target"));Files.writeString(Path.of("target/static-question-answer-assignment.json"),task.toJSONString(JSONWriter.Feature.WriteMapNullValue),StandardCharsets.UTF_8);
        assertEquals(0,rows("paiflow_model_operation"));
    }
    @Test void needReplyFalseStillWaitsThenConsumesRealResumeAndAcceptsBoundResult() throws Exception {
        var task=begun(canvas());var cp=checkpoint(task);assertEquals("WAITING",cp.get("state"));assertEquals(409,denied(()->checkpoints.consume(task.getString("runId"),cp.getString("checkpointId"),worker,consumeBody(task,cp))));
        var replied=reply(task,cp,"resume","用户实际回复");var body=consumeBody(task,replied);var consumed=checkpoints.consume(task.getString("runId"),cp.getString("checkpointId"),worker,body);assertTrue(consumed.getBooleanValue("consumed"));var resume=consumed.getJSONObject("resumeData");assertEquals("用户实际回复",JSON.parseObject(resume.getString("message")).get("content"));assertEquals(0,resume.getJSONObject("metadata").getIntValue("retries"));assertTrue(resume.getJSONObject("metadata").getLongValue("timestamp")>0);
        leases.result(task.getString("runId"),worker,result(task,"COMPLETED",JSONObject.of("answer","用户实际回复")));assertEquals("COMPLETED",runs.detail(task.getString("runId")).state());assertEquals(1,rows("paiflow_run_checkpoint"));
    }
    @Test void optionalIgnoreUsesOriginalEventAndDoesNotInventResumeContent() throws Exception {var task=begun(canvas());var cp=checkpoint(task);var replied=reply(task,cp,"ignore","");var value=checkpoints.consume(task.getString("runId"),cp.getString("checkpointId"),worker,consumeBody(task,replied));assertEquals(JSONObject.of("event_type","ignore","content",""),JSON.parseObject(value.getJSONObject("resumeData").getString("message")));}
    @Test void requiredIgnoreIsRejectedWithActualStateUnchanged() throws Exception {var raw=canvas();params(raw).put("needReply",true);var task=begun(raw);var cp=checkpoint(task);assertEquals(400,denied(()->reply(task,cp,"ignore","")));assertEquals("WAITING",checkpointMapper.find(cp.getString("checkpointId")).getState());assertNull(checkpointMapper.find(cp.getString("checkpointId")).getReplyKey());}
    @Test void abortMessageIsConsumedAsAbortAndWorkerFailedResultIsRetained() throws Exception {var task=begun(canvas());var cp=checkpoint(task);var reply=reply(task,cp,"abort","");var consumed=checkpoints.consume(task.getString("runId"),cp.getString("checkpointId"),worker,consumeBody(task,reply));assertEquals("abort",JSON.parseObject(consumed.getJSONObject("resumeData").getString("message")).get("event_type"));var failed=result(task,"FAILED",new JSONObject());failed.put("error",JSONObject.of("code",23802,"message","原问答终止"));leases.result(task.getString("runId"),worker,failed);assertEquals("FAILED",runs.detail(task.getString("runId")).state());assertEquals(23802,JSON.parseObject(runMapper.find(task.getString("runId")).getResultJson()).getJSONObject("error").getIntValue("code"));}
    @Test void checkpointExpirationNeverCreatesFakeReplyOrConsumedSuccess() throws Exception {var task=begun(canvas());var cp=checkpoint(task);clock.value=clock.value.plusSeconds(61);var poll=checkpoints.poll(task.getString("runId"),cp.getString("checkpointId"),worker,JSONObject.of("leaseId",task.get("leaseId"),"attempt",task.get("attempt"),"afterRevision",0));assertEquals("EXPIRED",poll.get("state"));assertFalse(checkpoints.consume(task.getString("runId"),cp.getString("checkpointId"),worker,consumeBody(task,poll)).getBooleanValue("consumed"));assertNull(checkpointMapper.find(cp.getString("checkpointId")).getResumeDataJson());}
    @Test void actualCurrentMenuRevocationBlocksUserReplyWithZeroReplyWrite() throws Exception {var task=begun(canvas());var cp=checkpoint(task);revoke("paiflow:run:resume");assertEquals(403,denied(()->reply(task,cp,"resume","不能保存")));assertNull(checkpointMapper.find(cp.getString("checkpointId")).getReplyHash());assertEquals("WAITING",checkpointMapper.find(cp.getString("checkpointId")).getState());}
    @Test void actualRunCreatePermissionRevocationBlocksWorkerConsume() throws Exception {var task=begun(canvas());var cp=checkpoint(task);var replied=reply(task,cp,"resume","已回复的真实事实");revoke("paiflow:run:create");assertEquals(403,denied(()->checkpoints.consume(task.getString("runId"),cp.getString("checkpointId"),worker,consumeBody(task,replied))));assertEquals("RESUMED",checkpointMapper.find(cp.getString("checkpointId")).getState());}
    @Test void removedMembershipBlocksReplyWithoutScopeWildcard() throws Exception {var task=begun(canvas());var cp=checkpoint(task);assertEquals(1,sql("UPDATE paiflow_space_member SET status='removed' WHERE space_id="+space+" AND user_id=42"));assertEquals(404,denied(()->reply(task,cp,"resume","被撤成员")));assertEquals("WAITING",checkpointMapper.find(cp.getString("checkpointId")).getState());}
    @Test void expiredReplyRefusesAndDoesNotPersistMessage() throws Exception {var task=begun(canvas());var cp=checkpoint(task);clock.value=clock.value.plusSeconds(61);assertEquals(410,denied(()->reply(task,cp,"resume","过期回复")));assertNull(checkpointMapper.find(cp.getString("checkpointId")).getReplyKey());}
    @Test void consumeReplayIsIdempotentAndDifferentReceiptNeverReconsumes() throws Exception {var task=begun(canvas());var cp=checkpoint(task);var replied=reply(task,cp,"resume","只消费一次");var body=consumeBody(task,replied);var first=checkpoints.consume(task.getString("runId"),cp.getString("checkpointId"),worker,body);long revision=checkpointMapper.find(cp.getString("checkpointId")).getRevision();assertEquals(first,checkpoints.consume(task.getString("runId"),cp.getString("checkpointId"),worker,body));assertEquals(revision,checkpointMapper.find(cp.getString("checkpointId")).getRevision());body.put("idempotencyKey","another_consume_key");assertEquals(409,denied(()->checkpoints.consume(task.getString("runId"),cp.getString("checkpointId").toString(),worker,body)));}
    @Test void foreignRunAndLeaseAttemptCannotConsumeCheckpoint() throws Exception {var first=begun(canvas());var cp=checkpoint(first);var replied=reply(first,cp,"resume","本轮回复");var second=begun(canvas());assertEquals(404,denied(()->checkpoints.consume(second.getString("runId"),cp.getString("checkpointId"),worker,consumeBody(second,replied))));var wrong=consumeBody(first,replied);wrong.put("attempt",2);assertEquals(409,denied(()->checkpoints.consume(first.getString("runId"),cp.getString("checkpointId"),worker,wrong)));assertEquals("RESUMED",checkpointMapper.find(cp.getString("checkpointId")).getState());}
    @Test void optionTrueHandleUsesNameAsInterruptIdAndPreservesOriginalOrder() throws Exception {var raw=canvas();params(raw).put("answerType","option");params(raw).getJSONObject("directAnswer").put("handleResponse",true);params(raw).put("optionAnswer",new JSONArray(List.of(option("B"),option("default"),option("A"))));var task=begun(raw);var cp=checkpoint(task);var question=checkpoints.detail(task.getString("runId"),cp.getString("checkpointId")).getJSONObject("question");assertEquals(List.of("B","default","A"),question.getJSONArray("option").stream().map(o->((JSONObject)o).getString("id")).toList());assertEquals("uuid-B",params(task.getJSONObject("dsl")).getJSONArray("optionAnswer").getJSONObject(0).get("id"));var replied=reply(task,cp,"resume","B");var consumed=checkpoints.consume(task.getString("runId"),cp.getString("checkpointId"),worker,consumeBody(task,replied));assertEquals("B",JSON.parseObject(consumed.getJSONObject("resumeData").getString("message")).get("content"));assertEquals(0,rows("paiflow_model_operation"));}
    private JSONObject option(String name){return JSONObject.of("id","uuid-"+name,"name",name,"type",2,"content_type","text","content",name);}
    @Test void versionV1NullKeepsOriginalHashThroughRestoreAndOnlyNewVersionGetsV3() throws Exception {
        var raw=canvas();var wf=workflows.create(space,JSONObject.of("name","old-v1-question","data",raw));long id=wf.getLongValue("id");var n=new DslCodec().normalizeV1(raw);var v=new WorkflowVersionRecord();v.setWorkflowId(id);v.setSpaceId(space);v.setOwnerUserId(42L);v.setSnapshotRevision(0L);v.setFlowId(wf.getString("flowId"));v.setVersionNum("source-v1");v.setName("source-v1");v.setCanvasJson(raw.toJSONString());v.setExecutionJson(n.execution().toJSONString());v.setMetadataJson("{}");v.setAdvancedConfigJson("{}");v.setFlowConfigJson("{}");v.setEngineProfile("python");v.setDslHash(n.executionHash());v.setCanonicalDslBase64(DslCodec.canonicalDslBase64(n.execution(),DslCodec.V1));v.setCreateBy("fixture");assertEquals(1,workflowMapper.insertVersion(v));
        assertEquals(DslCodec.V1,workflows.versionDetail(v.getId()).get("executionCodec"));assertEquals(n.execution(),workflows.runtimeSnapshot(v.getId()).execution());assertEquals(503,denied(()->runs.create(v.getId(),"python",new JSONObject(),"old_v1_question_key",300)));assertEquals(0,rows("paiflow_run"));
        workflows.restore(id,v.getId(),space,0L);assertNull(workflowMapper.version(v.getId()).getExecutionCodec());assertEquals(v.getDslHash(),workflowMapper.version(v.getId()).getDslHash());assertEquals(v.getCanonicalDslBase64(),workflowMapper.version(v.getId()).getCanonicalDslBase64());assertEquals(v.getExecutionJson(),workflowMapper.version(v.getId()).getExecutionJson());var current=workflows.createVersion(id,space,1L,JSONObject.of("name","new-v3"));assertEquals(DslCodec.V3,workflowMapper.version(current.getLongValue("id")).getExecutionCodec());assertEquals("",params(workflows.runtimeSnapshot(current.getLongValue("id")).execution()).get("domain"));
    }
    @Test void originalRequiredMenuAndAccountChecksRejectRunBeforeAnyQueueWrite() throws Exception {long v=version(canvas());revoke("paiflow:run:create");assertEquals(403,denied(()->runs.create(v,"python",new JSONObject(),"revoked_run_create_key",300)));assertEquals(0,rows("paiflow_run"));assertEquals(1,sql("UPDATE sys_menu SET status='0' WHERE perms='paiflow:run:create'"));assertEquals(1,sql("UPDATE sys_user SET status='1' WHERE user_id=42"));assertEquals(401,denied(()->runs.create(v,"python",new JSONObject(),"disabled_run_user_key",300)));assertEquals(0,rows("paiflow_run_event"));assertEquals(0,rows("paiflow_run"));}
    @Test void cancelledRunStopsWaitingWithoutInventingEngineCompleted() throws Exception {var task=begun(canvas());var cp=checkpoint(task);runs.cancel(task.getString("runId"));assertEquals("CANCEL_REQUESTED",runMapper.find(task.getString("runId")).getState());assertEquals(409,denied(()->leases.result(task.getString("runId"),worker,result(task,"COMPLETED",JSONObject.of("answer","late")))));assertEquals("CANCELLED",checkpoints.poll(task.getString("runId"),cp.getString("checkpointId"),worker,JSONObject.of("leaseId",task.get("leaseId"),"attempt",task.get("attempt"),"afterRevision",0)).get("state"));assertNull(runMapper.find(task.getString("runId")).getResultJson());}
    @Test void missingCheckpointAssemblyRejectsBeforeAnyRunOrEvent() throws Exception {long v=version(canvas());var missing=proxy(new RunService(workflows,runMapper,access,identities));assertEquals(503,denied(()->missing.create(v,"python",new JSONObject(),"missing_checkpoint_assembly",300)));assertEquals(0,rows("paiflow_run"));assertEquals(0,rows("paiflow_run_event"));}
    @Test void activeHistoryDirectModelHandlingAndExplicitNullRefuseVersionWithNoVersionWrite() throws Exception {for(String kind:List.of("history","v2history","model","null")){var raw=canvas();if(kind.equals("history"))params(raw).put("enableChatHistory",true);if(kind.equals("v2history"))params(raw).put("enableChatHistoryV2",JSONObject.of("isEnabled",true));if(kind.equals("model"))params(raw).getJSONObject("directAnswer").put("handleResponse",true);if(kind.equals("null"))params(raw).put("timeout",null);var wf=workflows.create(space,JSONObject.of("name",kind,"data",raw));assertEquals(kind.equals("null")?422:503,denied(()->workflows.createVersion(wf.getLongValue("id"),space,0L,new JSONObject())));}assertEquals(0,rows("paiflow_workflow_version"));assertEquals(0,rows("paiflow_run"));}
    @Test void oldV2QuestionVersionReconstructsOriginalBytesButCannotSilentlyRunOrUpgrade() throws Exception {var raw=canvas();var wf=workflows.create(space,JSONObject.of("name","old-v2-question","data",raw));var n=new DslCodec().normalize(raw,DslCodec.V2);var v=new WorkflowVersionRecord();v.setWorkflowId(wf.getLongValue("id"));v.setSpaceId(space);v.setOwnerUserId(42L);v.setSnapshotRevision(0L);v.setFlowId(wf.getString("flowId"));v.setVersionNum("historical-v2");v.setName("historical-v2");v.setDescription("");v.setCanvasJson(raw.toJSONString(JSONWriter.Feature.WriteMapNullValue));v.setExecutionJson(n.execution().toJSONString(JSONWriter.Feature.WriteMapNullValue));v.setMetadataJson("{}");v.setAdvancedConfigJson("{}");v.setFlowConfigJson("{}");v.setEngineProfile("python");v.setDslHash(n.executionHash());v.setCanonicalDslBase64(DslCodec.canonicalDslBase64(n.execution(),DslCodec.V2));v.setResourceSnapshotsJson("{}");v.setExecutionCodec(DslCodec.V2);v.setCreateBy("fixture");assertEquals(1,workflowMapper.insertVersion(v));assertEquals(n.execution(),workflows.runtimeSnapshot(v.getId()).execution());assertEquals("1.0",params(workflows.runtimeSnapshot(v.getId()).execution()).get("timeout"));assertEquals(503,denied(()->runs.create(v.getId(),"python",new JSONObject(),"old_question_v2_key",300)));assertEquals(0,rows("paiflow_run"));assertEquals(v.getCanonicalDslBase64(),workflowMapper.version(v.getId()).getCanonicalDslBase64());}
    @Test void malformedMixedModelNestedIterationVariablesAndActiveRetryAreRejectedBeforeVersionWrite() throws Exception {for(String type:List.of("spark-llm","iteration","node-variable")){var raw=canvas();raw.getJSONArray("nodes").add(JSONObject.of("id",type+"::mixed","data",new JSONObject()));var wf=workflows.create(space,JSONObject.of("name",type,"data",raw));assertEquals(type.equals("spark-llm")?422:503,denied(()->workflows.createVersion(wf.getLongValue("id"),space,0L,new JSONObject())));}var raw=canvas();data(raw,"question-answer::q").put("retryConfig",JSONObject.of("shouldRetry",true));var wf=workflows.create(space,JSONObject.of("name","retry","data",raw));assertEquals(503,denied(()->workflows.createVersion(wf.getLongValue("id"),space,0L,new JSONObject())));assertEquals(0,rows("paiflow_workflow_version"));assertEquals(0,rows("paiflow_model_operation"));}
    @Test void qaImplicitOutputAddressCannotAliasAnotherNodeButSameNodeDeclarationIsLegal(){var graph=WorkflowModelCompiler.compile(canvas(),(id,source,domain)->{throw new AssertionError("no model resolver");}).execution();data(graph,"question-answer::q").getJSONArray("outputs").add(JSONObject.of("name","query","schema",JSONObject.of("type","string")));assertEquals(1,StaticQuestionAnswerPolicy.validate(graph).pathCount());var other=JSONObject.of("id","question-answer::q-x","data",copy(data(graph,"question-answer::q")));other.getJSONObject("data").getJSONArray("outputs").removeIf(raw->"query".equals(((JSONObject)raw).get("name")));params(graph).put("opaque",null);data(graph,"question-answer::q").getJSONArray("outputs").add(JSONObject.of("name","x-query","schema",JSONObject.of("type","string")));graph.getJSONArray("nodes").add(other);graph.getJSONArray("edges").add(JSONObject.of("sourceNodeId","question-answer::q","targetNodeId","question-answer::q-x"));graph.getJSONArray("edges").add(JSONObject.of("sourceNodeId","question-answer::q-x","targetNodeId","node-end::e"));assertEquals(400,denied(()->StaticQuestionAnswerPolicy.validate(graph)));}
}
